{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    mins = [seg['minimum'] for seg in segments]
    caps = [seg['capacity'] for seg in segments]
    total_min = sum(mins)
    total_cap = sum(caps)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of range')
    alloc = mins[:]
    allocated = total_min
    while allocated < budget:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] >= caps[i]:
                continue
            score = seg['importance'] / (alloc[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        allocated += 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}
